import { CommonModule } from '@angular/common';
import { Component, OnInit, inject } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { MatRippleModule } from '@angular/material/core';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatProgressSpinnerModule } from '@angular/material/progress-spinner';
import { MatSelectModule } from '@angular/material/select';
import { ActivatedRoute, Router } from '@angular/router';

import {
    AsyncHandler,
    Building,
    BuildingLevel,
    Identity,
    OrganisationService,
    Region,
} from '@placeos/common';
import {
    SettingsToggleComponent,
    VirtualKeyboardComponent,
} from '@placeos/components';
import { first } from 'rxjs/operators';

@Component({
    selector: '[bootstrap]',
    template: `
        <div class="bg-base-200 absolute inset-0 z-0"></div>
        <div
            form
            class="border-base-300 bg-base-100 relative z-10 mx-auto my-8 w-md max-w-[calc(100%-2rem)] overflow-hidden rounded-lg border shadow-sm"
        >
            <header
                class="bg-secondary text-secondary-content flex w-full items-center justify-between px-4 py-3 text-xl font-medium"
            >
                <div>Map Kiosk</div>
                <div class="rounded-sm px-2 py-1 font-mono text-sm">SETUP</div>
            </header>
            @if (!loading) {
                <div class="flex flex-col px-4">
                    @if ((regions | async)?.length > 1) {
                        <label>Select a region from the dropdown below</label>
                        <mat-form-field
                            appearance="outline"
                            class="no-subscript"
                        >
                            <mat-select
                                #select
                                building
                                [(ngModel)]="active_region"
                                (ngModelChange)="setRegion($event)"
                                placeholder="Select region"
                            >
                                <mat-select-trigger>
                                    <div class="flex items-center space-x-4">
                                        <div class="flex-1 truncate">
                                            {{
                                                active_region?.display_name ||
                                                    active_region?.name
                                            }}
                                        </div>
                                        <div
                                            class="bg-base-200 mr-4! rounded-sm px-1.5 font-mono text-[0.625rem]"
                                        >
                                            {{ active_region?.id }}
                                        </div>
                                    </div>
                                </mat-select-trigger>
                                @for (option of regions | async; track option) {
                                    <mat-option [value]="option">
                                        <div class="leading-tight">
                                            <div>
                                                {{
                                                    option.display_name ||
                                                        option.name
                                                }}
                                            </div>
                                            <div
                                                class="font-mono text-[0.625rem] opacity-30"
                                            >
                                                <span class="hidden"
                                                    >&nbsp;[</span
                                                >{{ option.id
                                                }}<span class="hidden">]</span>
                                            </div>
                                        </div>
                                    </mat-option>
                                }
                            </mat-select>
                        </mat-form-field>
                    }
                    @if ((buildings | async)?.length) {
                        <label>Select a building from the dropdown below</label>
                        <mat-form-field
                            appearance="outline"
                            class="no-subscript"
                        >
                            <mat-select
                                #select
                                building
                                [(ngModel)]="active_building"
                                (ngModelChange)="setBuilding($event)"
                                placeholder="Select building"
                            >
                                <mat-select-trigger>
                                    <div class="flex items-center space-x-4">
                                        <div class="flex-1 truncate">
                                            {{
                                                active_building?.display_name ||
                                                    active_building?.name
                                            }}
                                        </div>
                                        <div
                                            class="bg-base-200 mr-4! rounded-sm px-1.5 font-mono text-[0.625rem]"
                                        >
                                            {{ active_building?.id }}
                                        </div>
                                    </div>
                                </mat-select-trigger>
                                @for (
                                    option of buildings | async;
                                    track option
                                ) {
                                    <mat-option [value]="option">
                                        <div class="leading-tight">
                                            <div>
                                                {{
                                                    option.display_name ||
                                                        option.name
                                                }}
                                            </div>
                                            <div
                                                class="font-mono text-[0.625rem] opacity-60"
                                            >
                                                <span class="hidden"
                                                    >&nbsp;[</span
                                                >{{ option.id
                                                }}<span class="hidden">]</span>
                                            </div>
                                        </div>
                                    </mat-option>
                                }
                            </mat-select>
                        </mat-form-field>
                    }
                    @if ((levels | async)?.length && active_building) {
                        <div></div>
                        <label>Select a level from the dropdown below</label>
                        <mat-form-field
                            appearance="outline"
                            class="no-subscript"
                        >
                            <mat-select
                                #select
                                level
                                [(ngModel)]="active_level"
                                placeholder="Select level"
                            >
                                <mat-select-trigger>
                                    <div class="flex items-center space-x-4">
                                        <div class="flex-1 truncate">
                                            {{
                                                active_level?.display_name ||
                                                    active_level?.name
                                            }}
                                        </div>
                                        <div
                                            class="bg-base-200 mr-4! rounded-sm px-1.5 font-mono text-[0.625rem]"
                                        >
                                            {{ active_level?.id }}
                                        </div>
                                    </div>
                                </mat-select-trigger>
                                @for (option of levels | async; track option) {
                                    <mat-option [value]="option">
                                        <div class="leading-tight">
                                            <div>
                                                {{
                                                    option.display_name ||
                                                        option.name
                                                }}
                                            </div>
                                            <div
                                                class="font-mono text-[0.625rem] opacity-30"
                                            >
                                                <span class="hidden"
                                                    >&nbsp;[</span
                                                >{{ option.id
                                                }}<span class="hidden">]</span>
                                            </div>
                                        </div>
                                    </mat-option>
                                }
                            </mat-select>
                        </mat-form-field>
                        @if (active_level?.tags.includes('parking')) {
                            <settings-toggle [(ngModel)]="parking" class="mt-2"
                                >Show as fixed parking display</settings-toggle
                            >
                        }
                    }
                    @if (rotations && rotations.length) {
                        <div></div>
                        <label>
                            Please select an orientation from the dropdown below
                        </label>
                        <mat-form-field
                            appearance="outline"
                            class="no-subscript"
                        >
                            <mat-select
                                #select
                                [(value)]="active_rotation"
                                placeholder="Select orientation"
                            >
                                @for (option of rotations; track option) {
                                    <mat-option [value]="option">
                                        <div class="leading-tight">
                                            <div>
                                                {{
                                                    option.display_name ||
                                                        option.name
                                                }}
                                            </div>
                                            <div
                                                class="font-mono text-[0.625rem] opacity-30"
                                            >
                                                <span class="hidden"
                                                    >&nbsp;[</span
                                                >{{ option.id
                                                }}<span class="hidden">]</span>
                                            </div>
                                        </div>
                                    </mat-option>
                                }
                            </mat-select>
                        </mat-form-field>
                    }
                    @if (locations && locations.length) {
                        <div></div>
                        <label>
                            Please select an fixed location from the dropdown
                            below
                        </label>
                        <mat-form-field
                            appearance="outline"
                            class="no-subscript"
                        >
                            <mat-select
                                #select
                                [(value)]="active_location"
                                placeholder="Select location"
                            >
                                @for (option of locations; track option) {
                                    <mat-option [value]="option">
                                        <div class="leading-tight">
                                            <div>
                                                {{
                                                    option.display_name ||
                                                        option.name
                                                }}
                                            </div>
                                            <div
                                                class="font-mono text-[0.625rem] opacity-30"
                                            >
                                                <span class="hidden"
                                                    >&nbsp;[</span
                                                >{{ option.id
                                                }}<span class="hidden">]</span>
                                            </div>
                                        </div>
                                    </mat-option>
                                }
                            </mat-select>
                        </mat-form-field>
                    }
                </div>
            } @else {
                <div class="m-auto flex flex-col items-center p-8">
                    <mat-spinner [diameter]="32"></mat-spinner>
                    <p>{{ loading }}</p>
                </div>
            }
            @if (!loading) {
                <div
                    class="border-base-300 mt-4! flex w-full items-center justify-end border-t px-4 py-2"
                >
                    <button
                        btn
                        matRipple
                        class="w-32"
                        [disabled]="!active_building && !active_level"
                        (click)="bootstrapKiosk()"
                    >
                        Finish Setup
                    </button>
                </div>
            }
        </div>
    `,
    styles: [
        `
            mat-form-field {
                width: 100%;
            }

            label {
                padding-top: 1rem;
            }
        `,
    ],
    imports: [
        MatRippleModule,
        MatProgressSpinnerModule,
        MatFormFieldModule,
        MatSelectModule,
        SettingsToggleComponent,
        CommonModule,
        FormsModule,
    ],
})
export class BootstrapComponent extends AsyncHandler implements OnInit {
    private _org = inject(OrganisationService);
    private _route = inject(ActivatedRoute);
    private _router = inject(Router);

    /** Loading state of the bootstrap */
    public loading: string;
    /** Actively selected building */
    public active_region: Region;
    /** Actively selected building */
    public active_building: Building;
    /** Actively selected level */
    public active_level: BuildingLevel;
    /** Actively selected level */
    public active_rotation: Identity;
    /** Actively selected location */
    public active_location: Identity;
    /** Whether to show the map as a parking view */
    public parking = false;

    public rotations: Identity[] = [];

    public readonly regions = this._org.region_list;
    public readonly buildings = this._org.active_buildings;
    public readonly levels = this._org.active_levels;

    public setRegion(region: Region) {
        this._org.region = region;
        this.active_building = undefined;
        this.active_level = undefined;
        this.updateRotations();
    }

    public setBuilding(building: Building) {
        this._org.building = building;
        this.active_level = undefined;
        this.updateRotations();
    }

    /** List of available locations */
    public get locations(): readonly Identity[] {
        if (!this.active_level) {
            return [];
        }
        return this.active_level.locations || [];
    }

    public async ngOnInit() {
        await this._org.initialised.pipe(first((_) => _)).toPromise();
        this.active_region = this._org.region;
        this.subscription(
            'route.query',
            this._route.queryParamMap.subscribe((params) => {
                if (params.has('osk')) {
                    const osk_enabled = params.get('osk') === 'true';
                    localStorage.setItem('OSK.enabled', `${osk_enabled}`);
                }
                if (params.has('clear') && params.get('clear') === 'true') {
                    localStorage.removeItem('KIOSK.building');
                    localStorage.removeItem('KIOSK.level');
                    localStorage.removeItem('KIOSK.parking');
                    localStorage.removeItem('KIOSK.orientation');
                }
                if (params.has('level')) {
                    const level = this._org.levelWithID([params.get('level')]);
                    if (level) {
                        this.active_level = level;
                        this.bootstrapKiosk();
                    }
                }
            }),
        );
        this.timeout('check', () => this.checkBootstrap(), 1000);
    }

    public updateRotations() {
        this.rotations = [];
        if (!this.active_building) return;
        const orientations = this.active_building.orientations;
        const rotations: Identity[] = [];
        for (const key in orientations) {
            if (orientations[key]) {
                rotations.push({
                    id: key,
                    name: `${key.split('_').join(' ')} (${
                        orientations[key] * 90
                    }°)`,
                    value: orientations[key],
                });
            }
        }
        this.rotations = rotations;
        this.active_rotation = this.rotations[0];
    }

    /**
     * Store bootstrapped values and navigate to the main page
     */
    public bootstrapKiosk() {
        this.loading = 'Bootstrapping application...';
        if (this.active_level) {
            if (localStorage) {
                localStorage.setItem(
                    'KIOSK.building',
                    this.active_building?.id || this.active_level.parent_id,
                );
                localStorage.setItem('KIOSK.level', this.active_level.id);
                if (this.parking) localStorage.setItem('KIOSK.parking', `true`);
                if (this.active_rotation) {
                    localStorage.setItem(
                        'KIOSK.orientation',
                        `${this.active_rotation.id}`,
                    );
                }
                if (this.active_location) {
                    localStorage.setItem(
                        'KIOSK.location',
                        `${this.active_location.id}`,
                    );
                }
            }
            this._router.navigate([this.parking ? '/parking' : '/explore']);
        }
        this.loading = null;
    }

    /**
     * Check for any existing bootstrapped values
     */
    private checkBootstrap() {
        this.loading = 'Checking for existing parameters...';
        const building_id = localStorage?.getItem('KIOSK.building');
        const level_id = localStorage?.getItem('KIOSK.level');
        const parking = localStorage?.getItem('KIOSK.parking');
        if (building_id && level_id) {
            this._router.navigate([parking ? '/parking' : '/explore']);
        }
        VirtualKeyboardComponent.enabled =
            localStorage.getItem('OSK.enabled') === 'true';
        this.loading = null;
    }
}
